import{_ as t,o as l,c as s,j as e,a as n,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/unterricht-kataloge/tutorials-zp10-teilleistungsarten.png",u="/bilder/unterricht-kataloge/tutorials-zp10-unterrichtsfaecher.png",d="/bilder/unterricht-kataloge/tutorials-zp10-teilleistungsarten-zuordnen.png",o="/bilder/unterricht-kataloge/tutorials-zp10-teilleistungsarten-zuordnen-gruppenprozess.png",g="/bilder/unterricht-kataloge/tutorials-zp10-teilleistungsarten-zuordnen-gruppenproozess-individuell.png",c="/bilder/unterricht-kataloge/tutorials-zp10-gp-ausfuehren.png",T=JSON.parse('{"title":"Fächer und Teilleistungen für ZP10 und Zentrale Klausuren vorbereiten","description":"","frontmatter":{"title":"Fächer und Teilleistungen für ZP10 und Zentrale Klausuren vorbereiten","source_pageid":1154,"source_revision":4344},"headers":[],"relativePath":"schild3/unterricht-kataloge/faecher-und-teilleistungen-fuer-zp-10-und-zk-tutorial.md","filePath":"schild3/unterricht-kataloge/faecher-und-teilleistungen-fuer-zp-10-und-zk-tutorial.md"}'),h={name:"schild3/unterricht-kataloge/faecher-und-teilleistungen-fuer-zp-10-und-zk-tutorial.md"};function p(f,r,k,m,z,b){return l(),s("div",null,[...r[0]||(r[0]=[e("h1",{id:"facher-und-teilleistungen-fur-zp10-und-zentrale-klausuren-vorbereiten",tabindex:"-1"},[n("Fächer und Teilleistungen für ZP10 und Zentrale Klausuren vorbereiten "),e("a",{class:"header-anchor",href:"#facher-und-teilleistungen-fur-zp10-und-zentrale-klausuren-vorbereiten","aria-label":'Permalink to "Fächer und Teilleistungen für ZP10 und Zentrale Klausuren vorbereiten"'},"​")],-1),e("p",null,"Legen Sie die benötigten Teilleistungsarten an und ordnen Sie diese den Prüfungsfächern zu. Danach können sie in die Leistungsdaten der Prüflinge übernommen werden.",-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Die grundlegende Einrichtung erläutert "),e("a",{href:"/schild3/schueler/teilleistungen-einrichten-und-verwalten-tutorial.html"},"Teilleistungen einrichten und verwalten"),n(".")]),e("p",null,[n("Den anschließenden Prüfungsablauf erläutert "),e("a",{href:"/schild3/schueler/zp10-zk-schueler.html"},"Daten der Zentralen Prüfung 10 erfassen"),n(".")])],-1),i('<p>Sollen ZP 10 und Zentrale Klausuren über SchILD-NRW erfasst und mittels der mitgelieferten Funktionen verarbeitet werden, sind hierfür die Fächer vorzubereiten und ihnen müssen passende Teilleistungen zugeordnet werden.</p><h2 id="konfiguration-der-kataloge" tabindex="-1">Konfiguration der Kataloge <a class="header-anchor" href="#konfiguration-der-kataloge" aria-label="Permalink to &quot;Konfiguration der Kataloge&quot;">​</a></h2><h3 id="anlegen-der-teilleistungen" tabindex="-1">Anlegen der Teilleistungen <a class="header-anchor" href="#anlegen-der-teilleistungen" aria-label="Permalink to &quot;Anlegen der Teilleistungen&quot;">​</a></h3><p><a href="/bilder/unterricht-kataloge/tutorials-zp10-teilleistungsarten.png"><img src="'+a+'" alt="Teilleistungsarten werden über Kataloge ➜ Teilleistungsarten definiert." loading="lazy"></a></p><p><em>Teilleistungsarten werden über Kataloge ➜ Teilleistungsarten definiert.</em></p><p>Bevor Teilleistungen einem Fach zugeordnet werden können, müssen diese über <strong>Kataloge ➜ Teilleistungsarten</strong> angelegt werden.</p><p>Für die ZP 10 ist eine <em>Vornote</em>, eine <em>Schriftliche Note</em> und eine <em>Abschlussnote</em> zu erfassen.</p><p>Die hier verwendeten Bezeichnungen sind beliebig zu wählen, sie sollten aber eindeutig und leicht erkennbar gewählt werden. Hier im Beispiel wurde die Zuordnung der Teilleistungen durch das Präfix <em>&quot;ZP 10 &quot;</em> kenntlich gemacht.</p><h3 id="unterrichtsfacher-konfigurieren" tabindex="-1">Unterrichtsfächer konfigurieren <a class="header-anchor" href="#unterrichtsfacher-konfigurieren" aria-label="Permalink to &quot;Unterrichtsfächer konfigurieren&quot;">​</a></h3><p><a href="/bilder/unterricht-kataloge/tutorials-zp10-unterrichtsfaecher.png"><img src="'+u+'" alt="Stellen Sie ein, ob ein Unterrichtsfach ein Schriftliches Prüfungsfach der ZP 10 oder einer Zentralen Klausur ist." loading="lazy"></a></p><p><em>Stellen Sie ein, ob ein Unterrichtsfach ein Schriftliches Prüfungsfach der ZP 10 oder einer Zentralen Klausur ist.</em></p><p>Wählen Sie unter <strong>Kataloge ➜ Unterrichtsfächer</strong> das Fach aus, das Teil der ZP 10 oder einer Zentralen Klausur ist.</p><p>Hierzu kann auch auf ein Fach oder eine Fachgruppe gefiltert werden.</p><p>Über die Haken rechts bei <em>Sonstige Einstellungen</em> wird gesetzt, ob ein Fach ein <strong>Schriftliches Prüfungsfach für ZP 10/ZK</strong> ist.</p><p>Der ältere Screenshot zeigt zusätzlich die Einstellung <strong>Nachprüfung</strong>. Diese Feldbezeichnung darf nicht mit der rechtlichen Zulässigkeit einer Nachprüfung zum Abschluss verwechselt werden. Für die Unterscheidung zur mündlichen Abweichungsprüfung beachten Sie <a href="/zeugnisse/zp10-rechtsstand.html">Notenbildung und mündliche Prüfung</a>. Eine mündliche ZP10-Prüfung auf Wunsch wird beim Prüfling erfasst; die Katalogeinstellung begründet keine gesetzliche Nachprüfungsmöglichkeit.</p><p>Wiederholen Sie diesen Vorgang für alle relevanten Fächer.</p><h3 id="zuweisen-der-teilleistungen-zu-den-fachern" tabindex="-1">Zuweisen der Teilleistungen zu den Fächern <a class="header-anchor" href="#zuweisen-der-teilleistungen-zu-den-fachern" aria-label="Permalink to &quot;Zuweisen der Teilleistungen zu den Fächern&quot;">​</a></h3><p><a href="/bilder/unterricht-kataloge/tutorials-zp10-teilleistungsarten-zuordnen.png"><img src="'+d+'" alt="Zuordnen der konkreten Teilleistungsarten zu einem der Unterrichtsfächer." loading="lazy"></a></p><p><em>Zuordnen der konkreten Teilleistungsarten zu einem der Unterrichtsfächer.</em></p><p>Nachdem die Fächer als Fächer der ZP 10/ZK markiert wurden und die Teilleistungen im Katalog definiert wurden, lassen sich die Teilleistungsarten nun den Fächern konkret zu weisen.</p><p>In <strong>Kataloge ➜ Unterrichtsfächer</strong> ist das passende Fach zu wählen, dann findet sich unter <em>Details</em> die Schaltfläche <code>Teilleistungsarten</code>.</p><p>Wurde diese angeklickt, sind alle diesem Fach zugeordneten Teilleistungsarten zu sehen. Ein Klick auf das <code>+</code> lässt uns die definierten <em>Teilleistungsarten</em> wählen.</p><p>Wählen Sie bei Bedarf zuerst die passende <strong>Kursart</strong> aus. Bei Unterricht im Klassenverband ist dies <strong>PUK</strong>. Sie können auch eine leere Kursart auswählen.</p><p>Setzen Sie nun die <em>Haken</em> bei den Teilleistungsarten, die für die ZP 10 oder die Zentrale Klausur definiert wurden.</p><p>Klicken Sie auf <code>Übernehmen</code>.</p>',25),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Wiederholen Sie diesen Vorgang für alle relevanten Fächer, bei der ZP 10 sind dies Deutsch, Mathematik und Englisch.")],-1),i('<h2 id="die-teilleistungsarten-den-leistungsdaten-bei-den-schulern-zuordnen" tabindex="-1">Die Teilleistungsarten den Leistungsdaten bei den Schülern zuordnen <a class="header-anchor" href="#die-teilleistungsarten-den-leistungsdaten-bei-den-schulern-zuordnen" aria-label="Permalink to &quot;Die Teilleistungsarten den Leistungsdaten bei den Schülern zuordnen&quot;">​</a></h2><p>Nun sind die Fächer und Teilleistungsarten für die Schule vorbereitet, sie müssen jedoch noch den Schülern konkret in ihren Leistungsdaten zugewiesen werden, damit die Teilleistungen aufgenommen werden können.</p><p><a href="/bilder/unterricht-kataloge/tutorials-zp10-teilleistungsarten-zuordnen-gruppenprozess.png"><img src="'+o+'" alt="Zuweisen der Teilleistungen zu den Leistungsdaten von konkreten Schülern, damit diese auch eingetragen werden können." loading="lazy"></a></p><p><em>Zuweisen der Teilleistungen zu den Leistungsdaten von konkreten Schülern, damit diese auch eingetragen werden können.</em></p><p>Es ist zuerst der <em>Jahrgang 10</em> auswählen, dann können die Teilleistungen über den Gruppenprozess <strong>Teilleistungsarten aus Vorlage zuweisen</strong> zugewiesen werden.</p><p>Sie sind damit dann bei den konfigurierten Fächern (D, M, E) angelegt und können nun in SchILD-NRW befüllt werden.</p>',6),e("div",{"data-hint-kind":"right",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"right","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"m8 12 3 3 5-6"})]),n("Richtig – Fertig")]),e("p",null,"Die Konfiguration ist abgeschlossen. Sie können die Noten nun wie gewohnt in den Leistungsdaten erfassen."),e("p",null,[n("Die Notenerfassung mit GradeHub und WeNoM ist dem SVWS-Server zugeordnet. Einrichtung und Bedienung sind in der "),e("a",{href:"https://doku.svws-nrw.de/",target:"_blank",rel:"noreferrer"},"SVWS-Dokumentation"),n(" beschrieben; siehe auch "),e("a",{href:"/zeugnisse/noteneingabe.html"},"Noten mit GradeHub und WeNoM erfassen"),n(".")])],-1),i('<h3 id="optional-individuell-konfigurierte-zuordnung-von-teilleistungen" tabindex="-1">Optional: Individuell konfigurierte Zuordnung von Teilleistungen <a class="header-anchor" href="#optional-individuell-konfigurierte-zuordnung-von-teilleistungen" aria-label="Permalink to &quot;Optional: Individuell konfigurierte Zuordnung von Teilleistungen&quot;">​</a></h3><p><a href="/bilder/unterricht-kataloge/tutorials-zp10-teilleistungsarten-zuordnen-gruppenproozess-individuell.png"><img src="'+g+'" alt="Eine individuellere Steuerung erlaubt der Gruppenprozess Teilleistungsarten indviduell zuweisen." loading="lazy"></a></p><p><em>Eine individuellere Steuerung erlaubt der Gruppenprozess Teilleistungsarten indviduell zuweisen.</em></p><p>Wenn Sie einzelne Teilleistungen nachtragen oder einer Teilgruppe andere Teilleistungsarten zuweisen möchten, verwenden Sie <strong>Teilleistungsarten individuell zuweisen</strong>.</p><p><a href="/bilder/unterricht-kataloge/tutorials-zp10-gp-ausfuehren.png"><img src="'+c+'" alt="Starten des Gruppenprozesses über &#39;Ausführen." loading="lazy"></a></p><p><em>Starten des Gruppenprozesses über &#39;Ausführen.</em></p><p>Klicken Sie oben auf <code>Ausführen</code>, um den konfigurierten Gruppenprozess zu starten.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=F%C3%A4cher_und_Teilleistungen_f%C3%BCr_ZP_10_und_ZK_(Tutorial)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 4344.</p>',9)])])}const w=t(h,[["render",p]]);export{T as __pageData,w as default};
